using System;using System.Collections.Generic;using System.IO;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using CityForge.Environment;
namespace CityForge.Editor {
[InitializeOnLoad] public static class GreenPatchPondStudy {
const string Root="Assets/CityForge/Art/Environment/GreenPatchPondStudy/";
const string Work="/Users/joelinstrum/Documents/Codex/2026-10-08/tre/work/";
static double captureAt;static GreenPatchPondStudy(){EditorApplication.update+=Tick;}
static Texture2D Tex(string name)=>AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/MicroVerse-Extras/Terrain Textures/Textures/"+name+"/"+name+"_BaseColor.png");
static void Tick(){if(EditorApplication.isCompiling||EditorApplication.isPlaying)return;if(File.Exists(Work+"green-patch-pond")){File.Delete(Work+"green-patch-pond");Run();}if(captureAt>0&&EditorApplication.timeSinceStartup>captureAt){captureAt=0;Capture();}}
[MenuItem("CityForge/Ground Study/Green Meadow Pond Patches")]
static void Run(){BuildWeights();var scene=EditorSceneManager.OpenScene("Assets/CityForge/Art/Environment/RollingPondStudy/RollingPondZoom1.unity");foreach(var go in scene.GetRootGameObjects()){if(!go.name.StartsWith("Ground with meadow")&&!go.name.StartsWith("Short meadow grass"))continue;var renderer=go.GetComponent<Renderer>();var mat=new Material(renderer.sharedMaterial);mat.shader=Shader.Find("CityForge/Green Patch Ground");mat.SetTexture("_Grass",Tex("Grass 04"));mat.SetTexture("_DryGrass",Tex("Grass 06"));mat.SetTexture("_Forest",Tex("Leaves 02"));mat.SetTexture("_Dirt",Tex("Soil 01"));mat.SetTexture("_Stone",Tex("Gravel 01"));for(int i=0;i<11;i++)mat.SetTexture("_T"+i,Tex(i<9?"Grass "+(i+1).ToString("00"):i==9?"Plantlet 01":"Soil 01"));for(int i=0;i<3;i++)mat.SetTexture("_Weights"+i,AssetDatabase.LoadAssetAtPath<Texture2D>(Root+"Weights"+i+".png"));string path=Root+(go.name.StartsWith("Ground")?"Ground":"Grass")+".mat";var old=AssetDatabase.LoadAssetAtPath<Material>(path);if(old){EditorUtility.CopySerialized(mat,old);UnityEngine.Object.DestroyImmediate(mat);mat=old;}else AssetDatabase.CreateAsset(mat,path);renderer.sharedMaterial=mat;}AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene,Root+"GreenPatchPondZoom1.unity");captureAt=EditorApplication.timeSinceStartup+3;}

static float Noise(float x,float z,float scale)=>Mathf.PerlinNoise(x/scale+19,z/scale+47);
static void BuildWeights(){
var rng=new System.Random(83473);var centers=new List<Vector2>();var palettes=new List<int[]>();var strength=new List<float[]>();
int[][] sets={new[]{0,1,2,3,9},new[]{0,2,3,8,9},new[]{0,4,5,6,10}};
for(int z=-1;z<10;z++)for(int x=-1;x<10;x++){var p=new Vector2((x+.15f+(float)rng.NextDouble()*.7f)*30,(z+.15f+(float)rng.NextDouble()*.7f)*30);centers.Add(p);palettes.Add(sets[rng.Next(3)]);var values=new float[5];int dominant=rng.Next(5);for(int i=0;i<5;i++)values[i]=i==dominant?5f:.25f+(float)rng.NextDouble()*.6f;strength.Add(values);}
var pixels=new[]{new Color[512*512],new Color[512*512],new Color[512*512]};var usage=new double[11];float maxError=0;
for(int z=0;z<512;z++)for(int x=0;x<512;x++){float wx=x*.5f,wz=z*.5f;var p=new Vector2(wx+(Noise(wx,wz,19)-.5f)*15,wz+(Noise(wx+137,wz-19,23)-.5f)*15);var weights=new float[11];float total=0;
for(int j=0;j<centers.Count;j++){float distance=(p-centers[j]).sqrMagnitude;if(distance>1800)continue;float influence=Mathf.Exp(-distance/110);for(int k=0;k<5;k++){int t=palettes[j][k];float local=Mathf.Lerp(.3f,1.7f,Noise(wx+t*39,wz-t*27,4+t%3*2));float w=influence*strength[j][k]*local*(t==10?.10f:t==4||t==5?.4f:1f);weights[t]+=w;total+=w;}}
float sum=0;for(int t=0;t<11;t++){float w=weights[t]/total;sum+=w;usage[t]+=w;var color=pixels[t/4][z*512+x];color[t%4]=w;pixels[t/4][z*512+x]=color;}maxError=Mathf.Max(maxError,Mathf.Abs(sum-1));}
for(int j=0;j<3;j++){var tex=new Texture2D(512,512,TextureFormat.RGBA32,false,true);tex.SetPixels(pixels[j]);tex.Apply();string path=Root+"Weights"+j+".png";File.WriteAllBytes(path,tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);AssetDatabase.ImportAsset(path);var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.sRGBTexture=false;importer.alphaSource=TextureImporterAlphaSource.FromInput;importer.alphaIsTransparency=false;importer.wrapMode=TextureWrapMode.Clamp;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.SaveAndReimport();}
File.WriteAllText(Work+"green-patch-validation.txt","Weight sum max error: "+maxError+"\nTexture coverage totals: "+string.Join(", ",usage)+"\n");
}
static void Capture(){var reflection=UnityEngine.Object.FindFirstObjectByType<PondPlanarReflection>();reflection.RenderNow();var camera=reflection.sourceCamera;var rt=new RenderTexture(3840,2160,24);rt.Create();var prev=RenderTexture.active;try{RenderPipeline.SubmitRenderRequest(camera,new UniversalRenderPipeline.SingleCameraRequest{destination=rt});RenderTexture.active=rt;var t=new Texture2D(3840,2160,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,3840,2160),0,0);t.Apply();File.WriteAllBytes("/Users/joelinstrum/Documents/Codex/2026-10-08/tre/outputs/GreenPatchPond_Zoom1.png",t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);}finally{RenderTexture.active=prev;rt.Release();UnityEngine.Object.DestroyImmediate(rt);}Debug.Log("GREEN PATCH POND CAPTURE COMPLETE");}
}}
